// Session evaluation — a line-by-line port of core/src/session.rs `evaluate`.
// Parity with the Rust crate is enforced by session.test.ts against
// parity-vectors.json, generated by core/examples/parity_vectors.rs.
// Instants are epoch milliseconds. Pure functions only.

export type PhaseKind = 'focus' | 'break';
export interface Segment { kind: PhaseKind; minutes: number }
export interface Phase { index: number; kind: PhaseKind; start: number; end: number }
export interface Occurrence { start: number; end: number; phases: Phase[] }

export type OverrideScope = 'current_focus_period' | 'rest_of_session';
export interface OverrideRecord {
  id: string;
  scope: OverrideScope;
  phaseIndex: number;
  requestedAt: number;
  delaySeconds: number;
  cancelledAt?: number;
}
export interface SessionControls { overrides: OverrideRecord[]; emergencyRecoveryAt?: number }

export type SessionStatus = 'upcoming' | 'active' | 'completed' | 'ended_by_override' | 'ended_by_emergency_recovery';
export type ReleaseReason = 'not_started' | 'scheduled_break' | 'override_current_focus_period'
  | 'session_ended_by_override' | 'emergency_recovery' | 'completed';
export type OverrideState =
  | { type: 'none' }
  | { type: 'pending'; scope: OverrideScope; effectiveAt: number }
  | { type: 'active_for_focus_period'; until: number };

export interface Snapshot {
  status: SessionStatus;
  phase: Phase | null;
  restricting: boolean;
  releaseReason: ReleaseReason | null;
  overrideState: OverrideState;
  nextTransition: number | null;
}

export const DEFAULT_OVERRIDE_DELAY_SECONDS = 90;
export const MAX_OVERRIDE_DELAY_SECONDS = 15 * 60;
export const MIN_FOCUS_MINUTES = 1;
export const MAX_FOCUS_MINUTES = 240;
export const MIN_BREAK_MINUTES = 1;
export const MAX_BREAK_MINUTES = 120;
export const MAX_SESSION_MINUTES = 12 * 60;
export const MAX_SEGMENTS = 41;

const MIN = 60_000;

/** `rounds` focus periods separated by breaks (same shape as SessionPlan::rounds). */
export function roundsPlan(rounds: number, focusMinutes: number, breakMinutes: number): Segment[] {
  const out: Segment[] = [];
  for (let i = 0; i < rounds; i++) {
    if (i > 0) out.push({ kind: 'break', minutes: breakMinutes });
    out.push({ kind: 'focus', minutes: focusMinutes });
  }
  return out;
}

/** Mirrors SessionPlan::validate. Returns a user-facing problem or null. */
export function validatePlan(segs: Segment[]): string | null {
  if (segs.length === 0) return 'Add at least one focus period.';
  if (segs.length > MAX_SEGMENTS) return `Use at most ${Math.ceil(MAX_SEGMENTS / 2)} focus periods.`;
  if (segs[0].kind !== 'focus' || segs[segs.length - 1].kind !== 'focus') return 'A session starts and ends with focus.';
  for (let i = 1; i < segs.length; i++) if (segs[i].kind === segs[i - 1].kind) return 'Focus periods and breaks must alternate.';
  let total = 0;
  for (const s of segs) {
    if (!Number.isInteger(s.minutes)) return 'Use whole minutes.';
    if (s.kind === 'focus' && (s.minutes < MIN_FOCUS_MINUTES || s.minutes > MAX_FOCUS_MINUTES))
      return `Focus periods are ${MIN_FOCUS_MINUTES}–${MAX_FOCUS_MINUTES} minutes.`;
    if (s.kind === 'break' && (s.minutes < MIN_BREAK_MINUTES || s.minutes > MAX_BREAK_MINUTES))
      return `Breaks are ${MIN_BREAK_MINUTES}–${MAX_BREAK_MINUTES} minutes.`;
    total += s.minutes;
  }
  if (total > MAX_SESSION_MINUTES) return 'A session can be at most 12 hours.';
  return null;
}

/** Elapsed-time phases from a start instant (an immediate session). */
export function occurrenceFrom(start: number, segs: Segment[]): Occurrence {
  let t = start;
  const phases = segs.map((s, index) => {
    const p = { index, kind: s.kind, start: t, end: t + s.minutes * MIN };
    t = p.end;
    return p;
  });
  return { start, end: t, phases };
}

const effectiveAt = (o: OverrideRecord) =>
  o.requestedAt + Math.min(o.delaySeconds, MAX_OVERRIDE_DELAY_SECONDS) * 1000;
const cancelledBy = (o: OverrideRecord, t: number) => o.cancelledAt !== undefined && o.cancelledAt <= t;

function origin(o: OverrideRecord, occ: Occurrence): Phase | null {
  const phase = occ.phases[o.phaseIndex];
  if (!phase) return null;
  const inside = phase.start <= o.requestedAt && o.requestedAt < phase.end;
  const kindOk = o.scope === 'current_focus_period' ? phase.kind === 'focus' : true;
  return inside && kindOk ? phase : null;
}

function takesEffect(o: OverrideRecord, occ: Occurrence): number | null {
  const org = origin(o, occ);
  if (!org) return null;
  const eff = effectiveAt(o);
  const limit = o.scope === 'current_focus_period' ? org.end : occ.end;
  if (eff >= limit || cancelledBy(o, eff)) return null;
  return eff;
}

export function evaluate(occ: Occurrence, controls: SessionControls, now: number): Snapshot {
  const emergencyAt = controls.emergencyRecoveryAt !== undefined && controls.emergencyRecoveryAt < occ.end
    ? controls.emergencyRecoveryAt : null;
  const sessionEffs = controls.overrides
    .filter((o) => o.scope === 'rest_of_session')
    .map((o) => takesEffect(o, occ))
    .filter((t): t is number => t !== null);
  const sessionOverrideAt = sessionEffs.length ? Math.min(...sessionEffs) : null;

  let status: SessionStatus;
  if (emergencyAt !== null && emergencyAt <= now) status = 'ended_by_emergency_recovery';
  else if (sessionOverrideAt !== null && sessionOverrideAt <= now) status = 'ended_by_override';
  else if (now < occ.start) status = 'upcoming';
  else if (now >= occ.end) status = 'completed';
  else status = 'active';

  const phase = status === 'active' ? occ.phases.find((p) => p.start <= now && now < p.end) ?? null : null;

  let overrideState: OverrideState = { type: 'none' };
  if (status === 'active') {
    for (const o of controls.overrides) {
      if (cancelledBy(o, now)) continue;
      const org = origin(o, occ);
      if (!org) continue;
      const eff = takesEffect(o, occ);
      if (eff === null) continue;
      const current = phase !== null && phase.index === org.index;
      if (o.scope === 'current_focus_period' && current && eff <= now) {
        overrideState = { type: 'active_for_focus_period', until: org.end };
        break;
      }
      if (eff > now && (current || o.scope === 'rest_of_session')) {
        overrideState = { type: 'pending', scope: o.scope, effectiveAt: eff };
      }
    }
  }

  const inFocus = phase?.kind === 'focus';
  const lifted = overrideState.type === 'active_for_focus_period';
  const restricting = status === 'active' && inFocus && !lifted;

  let releaseReason: ReleaseReason | null = null;
  if (!restricting) {
    releaseReason = ({
      upcoming: 'not_started', completed: 'completed', ended_by_override: 'session_ended_by_override',
      ended_by_emergency_recovery: 'emergency_recovery',
      active: lifted ? 'override_current_focus_period' : 'scheduled_break',
    } as const)[status];
  }

  const candidates = [occ.start, occ.end, ...occ.phases.map((p) => p.end)];
  if (emergencyAt !== null) candidates.push(emergencyAt);
  for (const o of controls.overrides) {
    if (origin(o, occ)) {
      candidates.push(effectiveAt(o));
      if (o.cancelledAt !== undefined) candidates.push(o.cancelledAt);
    }
  }
  const ended = status !== 'upcoming' && status !== 'active';
  const future = candidates.filter((t) => t > now && t <= occ.end);
  const nextTransition = ended || future.length === 0 ? null : Math.min(...future);

  return { status, phase, restricting, releaseReason, overrideState, nextTransition };
}
